window.NVC = window.NVC || {};

(window.NVC.scenarios = window.NVC.scenarios || []).push(
{ id:"family", name:"Family & Parenting", icon:"🏠", hue:28, blurb:"From toddler meltdowns to aging parents, practice turning everyday family friction into connection.", cases:[
{ id:"family-01", title:"Supermarket meltdown", context:"Three-year-old Mateo throws himself on the floor in the checkout line because he can’t have the candy bar.", who:"child", level:1,
  jackal:"Stop it right now! Everyone is staring at you. You’re being a brat.",
  giraffe:{ o:"You’re lying on the floor crying since I said no to the candy.", f:"I’m feeling flustered and a bit tired", n:"I need us both to feel safe and calm", r:"Would you like to hold my hand or hold the shopping list while we finish?" },
  say:"Oh, you really wanted that candy and I said no. That’s so hard. I’m here. You can hold my hand or the list — which one?",
  empathy:"Are you feeling really disappointed because you wanted something sweet and wanted a say in it?",
  tip:"Get down to eye level and take a slow breath first; your own calm is the most powerful tool you have in a tantrum." },
{ id:"family-02", title:"Siblings fighting over tablet", context:"Aisha (8) and Omar (6) are shouting and grabbing the tablet from each other in the living room.", who:"child", level:1,
  jackal:"That’s it, nobody gets the tablet! You two can never share anything.",
  giraffe:{ o:"I see two hands pulling on one tablet and I hear yelling.", f:"I feel tense", n:"I want everyone to be treated fairly and the tablet to stay safe", r:"Can you both put it on the table and tell me your idea for taking turns?" },
  say:"Whoa, two people, one tablet, lots of yelling. Let’s put it down on the table. What’s a plan that feels fair to both of you?",
  empathy:"Are you each feeling frustrated because you want a fair turn and want to be heard?",
  tip:"Hand the problem back to them with a timer; kids follow solutions they invent far better than ones we impose." },
{ id:"family-03", title:"Dishes left in sink", context:"It’s 9 p.m. and the dishes 15-year-old Priya agreed to wash after dinner are still in the sink.", who:"teen", level:1,
  jackal:"You’re so lazy. I do everything around here and you can’t even manage one chore.",
  giraffe:{ o:"The dinner dishes are still in the sink and it’s nine o’clock.", f:"I’m feeling disappointed and worn out", n:"I need cooperation and to trust our agreements", r:"Would you be willing to wash them in the next fifteen minutes?" },
  say:"Hey Priya, I noticed the dinner dishes are still in the sink. I’m pretty wiped out tonight and I was counting on our deal. Could you get to them in the next fifteen minutes?",
  empathy:"Are you feeling overwhelmed tonight and wanting some downtime before tackling one more thing?",
  tip:"Name the specific chore and a time; vague requests like “help out more” invite vague results." },
{ id:"family-04", title:"Bedtime stalling", context:"Five-year-old Lily has asked for water, a second story and another hug, and it’s 30 minutes past bedtime.", who:"child", level:1,
  jackal:"If you get out of bed one more time, no stories tomorrow!",
  giraffe:{ o:"This is the third time you’ve come out since lights out.", f:"I’m feeling impatient and tired", n:"I need rest, and I want your body to get the sleep it needs", r:"Would you like to choose one stuffed animal to snuggle while I sit by the door for two minutes?" },
  say:"You keep coming out — I think part of you isn’t ready to say goodnight. I’m tired too. Pick one snuggly friend, and I’ll sit by your door for two minutes.",
  empathy:"Are you feeling a little lonely or scared at night and wanting more closeness with me?",
  tip:"Stalling often signals a need for connection; front-load ten minutes of undivided attention before lights out." },
{ id:"family-05", title:"Screen time is over", context:"Nine-year-old Kenji yells “That’s so unfair!” when his tablet timer goes off in the middle of a game.", who:"child", level:1,
  jackal:"Stop whining. You’re addicted to that thing.",
  giraffe:{ o:"The timer rang and you shouted that it’s unfair.", f:"I feel concerned", n:"I value balance and keeping our agreements", r:"Would you like two minutes to save your game, then hand it to me?" },
  say:"Ugh, the timer went off right in the middle of your level — that’s annoying. Take two minutes to save, then it’s my turn to hold the tablet.",
  empathy:"Are you frustrated because you were so close to finishing and want some control over when you stop?",
  tip:"Give a five-minute warning before the end; transitions are easier when a child can find a stopping point." },
{ id:"family-06", title:"Homework battle", context:"Ten-year-old Sofia has been staring at the same maths worksheet for 40 minutes, saying “I’m stupid, I can’t do it.”", who:"child", level:2,
  jackal:"You’re not stupid, you’re just not trying. Stop being dramatic and finish it.",
  giraffe:{ o:"You’ve been on this worksheet for 40 minutes and you said you’re stupid.", f:"I feel sad hearing that", n:"I want you to have confidence and support while learning", r:"Would you be willing to show me the one problem that feels hardest so we can look at it together?" },
  say:"Forty minutes on one sheet — no wonder you’re fed up. It makes me sad to hear you call yourself stupid. Want to show me the toughest one and we’ll look at it together?",
  empathy:"Are you feeling discouraged and wanting to feel capable and understood?",
  tip:"Connect before you correct: acknowledge the frustration before explaining any maths." },
{ id:"family-07", title:"Mother-in-law criticizes parenting", context:"At Sunday lunch, Grace’s mother-in-law Margaret says, “In my day, children weren’t allowed to talk back like that.”", who:"older", level:3,
  jackal:"Well, it’s not your day anymore, and they’re not your kids.",
  giraffe:{ o:"When you said children weren’t allowed to talk back in your day, while Ella was speaking,", f:"I felt uncomfortable and a little hurt", n:"because I need respect for how we’re choosing to raise our children", r:"Would you be willing to talk with me privately next time you have a concern about the kids?" },
  say:"Margaret, when you mentioned kids not talking back in your day while Ella was speaking, I felt a bit hurt. I really want us to be on the same team. Could you bring concerns to me privately next time?",
  empathy:"Are you worried about the children and wanting your experience to be valued?",
  tip:"Guess the positive intent behind criticism from elders — often it’s care and wanting to still matter." },
{ id:"family-08", title:"Partner undermines discipline", context:"Chidi told their son no dessert before homework, then his wife Ngozi gave him ice cream anyway.", who:"adult", level:2,
  jackal:"Thanks for making me look like the bad guy again. You always undermine me.",
  giraffe:{ o:"After I told Tobi no dessert before homework, I saw him eating ice cream you’d given him.", f:"I felt frustrated and a bit alone", n:"I need us to be consistent and to support each other as parents", r:"Could we spend ten minutes tonight agreeing on our dessert rule?" },
  say:"Hey, earlier I told Tobi no dessert until homework was done, and then he had ice cream from you. I felt kind of alone in it. Can we take ten minutes tonight to agree on a rule together?",
  empathy:"Were you wanting to give him a little joy after a hard day, and maybe didn’t know what I’d said?",
  tip:"Have parenting disagreements away from the kids, then present a united front." },
{ id:"family-09", title:"Teen wants expensive shoes", context:"Sixteen-year-old Diego insists he needs $200 sneakers because “everyone has them.”", who:"teen", level:2,
  jackal:"Do you think money grows on trees? You’re so spoiled.",
  giraffe:{ o:"You’ve asked for the $200 sneakers three times this week.", f:"I feel torn", n:"I care about you fitting in and also about our family budget", r:"Would you be willing to look at our clothing budget with me and come up with a plan to earn the difference?" },
  say:"I can tell these shoes really matter to you — you’ve asked a few times. I’m torn, because I want you to feel good at school and we also have a budget. Want to sit down and figure out how you could earn the rest?",
  empathy:"Are you feeling anxious about belonging and wanting to be seen as part of the group?",
  tip:"Teens learn money skills best when they have real choices and a stake in the outcome." },
{ id:"family-10", title:"“You’re not my dad”", context:"During an argument about chores, 11-year-old stepdaughter Zoe shouts at Marcus, “You’re not my real dad, you can’t tell me what to do!”", who:"child", level:3,
  jackal:"As long as you live under my roof, you’ll do what I say.",
  giraffe:{ o:"When I asked about the laundry, you said I’m not your real dad.", f:"I feel sad and a little shaken", n:"I need us to have respect and trust between us", r:"Would you be willing to tell me what it’s like for you having me in the house?" },
  say:"You’re right, I’m not your dad, and I’m not trying to replace him. That stung a bit though. I’d really like to know — what’s it been like for you having me around?",
  empathy:"Are you feeling unsure and wanting your loyalty to your dad and your own choices to be respected?",
  tip:"In blended families, stepparents usually build connection first and leave most discipline to the biological parent at the start." },
{ id:"family-11", title:"Picky eater at dinner", context:"Four-year-old Ravi pushes his plate away and announces, “Yuck, I hate vegetables.”", who:"child", level:1,
  jackal:"You’ll sit there until you eat every bite. There are starving children in the world.",
  giraffe:{ o:"You pushed your plate away and said yuck.", f:"I feel a little worried", n:"I care about your body getting good food", r:"Would you like to try one tiny bite of carrot, or just smell it first?" },
  say:"Hmm, not a fan tonight, huh? I care about your body getting good food. Want to try a tiny bite of carrot, or just give it a sniff?",
  empathy:"Are you wanting to choose for yourself what goes in your body?",
  tip:"Offer without pressure; children often need many low-stakes exposures to a new food before accepting it." },
{ id:"family-12", title:"Sibling won’t help with Mom", context:"Fatima has handled all their elderly mother’s appointments for a year while her brother Yusuf, who lives nearby, rarely visits.", who:"adult", level:3,
  jackal:"You’ve completely abandoned Mom. You’re selfish and you always have been.",
  giraffe:{ o:"In the last year I’ve taken Mom to all twelve of her appointments, and you’ve visited twice.", f:"I’m feeling exhausted and resentful", n:"I need shared responsibility and some rest", r:"Would you be willing to take the next two appointments, on the 4th and the 18th?" },
  say:"Yusuf, I’ve taken Mom to every appointment this year and I’m running on empty. I really need us to share this. Could you take the ones on the 4th and the 18th?",
  empathy:"Is it possible you’re feeling overwhelmed or guilty, and wanting to help in a way that fits your life?",
  tip:"Make the request specific and small; a concrete date is easier to say yes to than “do more.”" },
{ id:"family-13", title:"Grandpa’s endless sweets", context:"Every visit, Grandpa Hiroshi gives the kids candy right before dinner even though their mum Yuki has asked him not to.", who:"older", level:2,
  jackal:"Dad, you never listen to me. You’re ruining their dinners on purpose.",
  giraffe:{ o:"Today the kids had candy from you about ten minutes before dinner.", f:"I feel frustrated", n:"I need support with their routines and nutrition", r:"Would you be willing to save treats for after dinner and make it your special dessert ritual?" },
  say:"Dad, I love how much the kids adore you. When they get candy right before dinner they don’t eat, and I get frustrated. Could treats be your special after-dinner thing with them?",
  empathy:"Are you wanting to bring them joy and have a special bond that’s just yours?",
  tip:"Offer a strategy that still meets the grandparent’s need for a special role." },
{ id:"family-14", title:"Hitting the baby", context:"Three-year-old Noor hits her newborn brother on the head while their dad changes his diaper.", who:"child", level:2,
  jackal:"Bad girl! We don’t hit babies! Go to your room!",
  giraffe:{ o:"You hit Sami on the head.", f:"I feel scared", n:"I need everyone in our family to be safe", r:"Can you show me gentle hands, or come squeeze this pillow if you feel mad?" },
  say:"I won’t let you hit Sami. I need everybody safe. You seem really mad. Show me gentle hands, or come squeeze this pillow as hard as you want.",
  empathy:"Are you feeling left out and wanting to know you’re still special to us since the baby came?",
  tip:"Stop the behavior firmly, then give extra one-on-one time; jealousy of a new sibling is normal and needs connection." },
{ id:"family-15", title:"Bedroom mess", context:"Eight-year-old Lucas’s bedroom floor is covered in clothes, Lego and plates from snacks.", who:"child", level:1,
  jackal:"Your room is a pigsty. Why can’t you be tidy like your sister?",
  giraffe:{ o:"I see clothes, Lego and two plates on your floor.", f:"I feel uneasy", n:"I need order and for food not to attract bugs", r:"Would you be willing to bring the plates to the kitchen now and pick up the Lego before dinner?" },
  say:"Buddy, there are plates and Lego all over the floor. The plates worry me because of bugs. Could you take them to the kitchen now and get the Lego in the bin before dinner?",
  empathy:"Does cleaning feel overwhelming when there’s so much, and would some help getting started be nice?",
  tip:"Break big tasks into small, visible steps; “clean your room” is too abstract for most kids." },
{ id:"family-16", title:"Slammed bedroom door", context:"After being told she can’t go to a concert, 14-year-old Maya stomps upstairs and slams her door.", who:"teen", level:2,
  jackal:"Slam that door again and I’m taking it off the hinges!",
  giraffe:{ o:"You slammed your door after I said no to the concert.", f:"I feel startled", n:"I want our home to feel calm and safe", r:"When you’re ready, would you be willing to tell me what the concert means to you?" },
  say:"That door slam told me you’re really upset. I get it — this concert means a lot. When you’re ready, I want to hear what it means to you.",
  empathy:"Are you feeling furious because you want more freedom and to be trusted?",
  tip:"Address the feeling behind the behavior later, once both of you have calmed down." },
{ id:"family-17", title:"Dad should stop driving", context:"Eighty-two-year-old Walter has had two small fender-benders this year, and his daughter Rosa wants to talk about him giving up driving.", who:"older", level:3,
  jackal:"You’re going to kill someone, Dad. You’re too old to drive.",
  giraffe:{ o:"You’ve had two fender-benders since January.", f:"I’m scared", n:"I need to know you and others are safe, and I care about your independence", r:"Would you be willing to take a driving assessment with your doctor next month?" },
  say:"Dad, after the two bumps this year I’ve been really scared for you. I know how much your independence matters. Would you be open to a driving assessment with your doctor next month?",
  empathy:"Are you afraid of losing your freedom and wanting to be trusted to make your own choices?",
  tip:"Lead with care for their dignity and autonomy; offer a neutral third party, like a doctor, to assess." },
{ id:"family-18", title:"Fibbing about teeth", context:"Six-year-old Amara says she brushed her teeth, but her toothbrush is completely dry.", who:"child", level:1,
  jackal:"You’re a liar. I can’t trust anything you say.",
  giraffe:{ o:"You said you brushed, and your toothbrush is dry.", f:"I feel puzzled", n:"I want honesty and healthy teeth for you", r:"Would you like to brush now while I sing the two-minute song?" },
  say:"Hmm, your toothbrush is still dry. I think maybe brushing felt boring tonight. Let’s do it now — I’ll sing the two-minute song!",
  empathy:"Were you tired and wanting to skip a boring step, and maybe worried I’d be upset?",
  tip:"Don’t ask questions you already know the answer to; it sets children up to lie." },
{ id:"family-19", title:"Adult son back home", context:"Twenty-six-year-old Andre moved back home six months ago and hasn’t contributed rent or chores.", who:"adult", level:2,
  jackal:"You’re a freeloader. When I was your age I had a job and a family.",
  giraffe:{ o:"In the six months you’ve been home, we haven’t agreed on rent or chores.", f:"I feel uneasy and a bit resentful", n:"I need fairness and to feel like partners in this household", r:"Could we sit down Sunday and agree on a monthly contribution and two weekly chores?" },
  say:"Andre, I’m glad you’re here. It’s been six months and we never sorted out rent or chores, and I’m starting to feel resentful. Can we sit down Sunday and agree on what that looks like?",
  empathy:"Are you feeling discouraged about your situation and wanting to be respected as an adult?",
  tip:"Address the arrangement early and treat your adult child as a housemate who can negotiate." },
{ id:"family-20", title:"Ex is late for pickups", context:"Co-parent Liam has been 30–45 minutes late for the last four Friday handovers, leaving their kids waiting at the door.", who:"adult", level:3,
  jackal:"You obviously don’t care about the kids. Typical you.",
  giraffe:{ o:"The last four Fridays, you arrived 30 to 45 minutes after six.", f:"I feel frustrated and worried", n:"I need predictability for the kids and for my own plans", r:"Would you be willing to text me by 5:30 if you’ll be later than six?" },
  say:"Liam, the last four Fridays you got here 30 to 45 minutes late, and the kids sat waiting at the door. I need predictability for them. Could you text me by 5:30 if you’re going to be late?",
  empathy:"Are you feeling stretched with work and wanting some understanding?",
  tip:"Keep co-parent messages brief, factual and friendly; Bill Eddy’s BIFF method is a useful model." },
{ id:"family-21", title:"Who hosts the holidays", context:"Three adult siblings argue in a group chat; Daniel says Elena “always makes it about her” when she offers to host again.", who:"adult", level:2,
  jackal:"Fine, I’ll never host again. Nobody appreciates anything I do.",
  giraffe:{ o:"When you wrote that I always make it about me,", f:"I felt hurt", n:"I need appreciation and a fair say in our family traditions", r:"Would you be willing to jump on a call this weekend to decide together how we rotate hosting?" },
  say:"Daniel, reading that I always make it about me really hurt. I just love having everyone over. Could we hop on a call this weekend and work out a rotation that feels fair to all of us?",
  empathy:"Are you wanting to have a turn at contributing and to feel equally included?",
  tip:"Move emotional topics out of group chats and into a voice call; tone gets lost in text." },
{ id:"family-22", title:"After I yelled at my kids", context:"Hana snapped and yelled at her kids during a chaotic morning and is now sitting in the car feeling awful.", who:"self", level:2,
  jackal:"I’m a terrible mother. I always lose it. My kids deserve better.",
  giraffe:{ o:"This morning I raised my voice when we were running late.", f:"I feel regretful and sad", n:"I need peace and to be the calm, caring parent I want to be", r:"Can I take three deep breaths now and plan to repair with the kids after school?" },
  say:"I yelled this morning and I feel sad about it, because I really value being calm with them. I’ll breathe, forgive myself, and tell them tonight, “I’m sorry I yelled — I was stressed and it wasn’t your fault.”",
  empathy:"Am I exhausted and in need of more support and rest myself?",
  tip:"Repair matters more than perfection; apologizing to children models exactly the skills we want them to learn (Dan Siegel calls this rupture and repair)." }
]}
,
{ id:"school", name:"School & Classroom", icon:"🏫", hue:48, blurb:"Practice honest, caring language between teachers, students, parents and classmates.", cases:[
{ id:"school-01", title:"Constant calling out", context:"Seven-year-old Ethan keeps shouting answers during Ms. Okafor’s reading lesson before other children can raise their hands.", who:"child", level:1,
  jackal:"Ethan, how many times do I have to tell you? Stop being so rude!",
  giraffe:{ o:"Ethan, that’s the fourth answer you’ve called out without raising your hand.", f:"I feel a little frustrated", n:"because I want everyone to have a chance to think and share", r:"Can you show me your hand in the air and wait for my nod?" },
  say:"Ethan, you’ve got so many ideas today! That’s four called-out answers, though, and I want everyone to get a turn to think. Show me a raised hand and wait for my nod, okay?",
  empathy:"Are you feeling excited and wanting to show what you know?",
  tip:"Give eager students a job, like writing their answer on a mini whiteboard, so their energy has somewhere to go." },
{ id:"school-02", title:"Head down, not working", context:"Fifteen-year-old Jasmine has had her head on her desk for the whole science lab while her partner works alone.", who:"teen", level:2,
  jackal:"Wake up, Jasmine. If you don’t want to learn, you can go to the office.",
  giraffe:{ o:"I’ve noticed your head’s been down for the whole lab today.", f:"I’m concerned", n:"because I care about how you’re doing and about your learning", r:"Would you be willing to step outside with me for a minute so we can talk?" },
  say:"Hey Jasmine, I’ve noticed your head’s been down all period. I’m a bit worried about you. Could we step out for a quick minute and talk?",
  empathy:"Are you feeling exhausted or weighed down by something and needing some understanding?",
  tip:"Talk privately; public confrontation with a teen usually escalates into a power struggle." },
{ id:"school-03", title:"Angry parent email", context:"A parent, Mr. Novak, emails in capitals that his son’s C grade is “completely unfair” and that the teacher “clearly has it out for him.”", who:"adult", level:3,
  jackal:"Your son earned that grade. Maybe if he did his homework he’d do better.",
  giraffe:{ o:"I read your email about Adam’s C on the history project.", f:"I can hear you’re really upset, and I feel concerned too", n:"I want Adam to succeed and to be graded fairly", r:"Would you be willing to meet this Thursday at 3:30 so we can go through the rubric together?" },
  say:"Thank you for writing, Mr. Novak. I can tell you’re really upset about Adam’s grade, and I want him to succeed too. Could we meet Thursday at 3:30 and look at the rubric and his work together?",
  empathy:"Are you feeling worried about Adam’s future and wanting to be sure he’s treated fairly?",
  tip:"Don’t reply to a heated email while you’re heated; wait, empathize first, and move the conversation to a meeting." },
{ id:"school-04", title:"Pushing in line", context:"In the lunch line, six-year-old Chloe pushes past Ben, who says to his teacher that it’s not fair.", who:"child", level:1,
  jackal:"Chloe, you’re always pushing. Go to the back of the line.",
  giraffe:{ o:"Chloe, I saw you push past Ben to get to the front.", f:"I feel worried", n:"because I want everyone to be safe and to get a fair turn", r:"Can you tell Ben you’re sorry and walk back to your place?" },
  say:"Chloe, you pushed past Ben. I want everybody safe in line and getting a fair turn. Can you check in with Ben and walk back to your spot?",
  empathy:"Are you feeling really hungry and wanting to get your lunch quickly?",
  tip:"Coach the child who was pushed to speak up too: “I don’t like it when you push. Please wait your turn.”" },
{ id:"school-05", title:"Witnessing bullying", context:"Nine-year-old Kofi tells his teacher that some boys keep taking Liam’s hat and throwing it around at recess.", who:"child", level:2,
  jackal:"Stop telling tales, Kofi. Just stay out of it.",
  giraffe:{ o:"You’re telling me you saw the boys taking Liam’s hat at recess.", f:"I feel grateful you told me", n:"because I want every student to feel safe here", r:"Will you tell me exactly what you saw, and where it happened?" },
  say:"Kofi, thank you for telling me. That took courage. I want Liam and everyone to feel safe at school. Can you tell me exactly what you saw and where?",
  empathy:"Are you feeling worried for Liam and wanting things to be fair and kind?",
  tip:"Teach the difference between “tattling” (to get someone in trouble) and “telling” (to get someone help)." },
{ id:"school-06", title:"Standing up to a bully", context:"Twelve-year-old Mei keeps hearing a classmate, Tyler, mock her accent when she answers questions in class.", who:"peer", level:3,
  jackal:"Shut up, Tyler. At least I’m not an idiot like you.",
  giraffe:{ o:"When you copy the way I talk after I answer in class,", f:"I feel hurt and angry", n:"because I want to be respected for who I am", r:"Will you stop doing that starting today?" },
  say:"Tyler, when you copy my accent after I answer, it hurts and it makes me angry. I want respect. Stop doing it, starting today.",
  empathy:"Are you wanting attention or laughs from the others and maybe not thinking how it lands?",
  tip:"Say it once, clearly and calmly, then tell a trusted adult if it continues; you don’t have to handle bullying alone." },
{ id:"school-07", title:"Group project slacker", context:"Three days before the deadline, Rahul still hasn’t done his section of the group presentation.", who:"peer", level:2,
  jackal:"Thanks for nothing, Rahul. We’re doing all the work and you’ll get the same grade.",
  giraffe:{ o:"The presentation’s due Friday and your slides aren’t in the shared folder yet.", f:"I’m feeling anxious", n:"because I want us to do well together and share the work fairly", r:"Could you add your three slides by tomorrow at 6 p.m.?" },
  say:"Hey Rahul, it’s due Friday and your slides aren’t in the folder yet. I’m getting nervous. Could you add your three by tomorrow at six? Let me know if you’re stuck on something.",
  empathy:"Are you feeling overwhelmed or unsure how to start your part?",
  tip:"Agree on mini-deadlines at the very first group meeting; it prevents the last-minute scramble." },
{ id:"school-08", title:"Test anxiety", context:"Before the final exam, 16-year-old Isabella tells her teacher, “I’m going to fail. I always freeze up.”", who:"teen", level:1,
  jackal:"Oh, don’t be silly. You’ll be fine. Just stop worrying.",
  giraffe:{ o:"You said you’re going to fail and that you freeze up.", f:"I hear how nervous you are", n:"and I want you to feel prepared and supported", r:"Would you like to try a slow breath with me and then look at the first question together?" },
  say:"It sounds like you’re really nervous — freezing up is so stressful. Let’s take a slow breath together. Then we’ll look at the first question, one step at a time.",
  empathy:"Are you feeling scared because doing well matters to you and you want to show what you know?",
  tip:"Reassurance (“don’t worry”) often feels dismissive; acknowledging the fear first helps it settle." },
{ id:"school-09", title:"Colleague comments on noise", context:"In the staff room, a fellow teacher, Mrs. Harper, says loudly, “I could hear your class through the wall again. Zoo day?”", who:"adult", level:2,
  jackal:"Maybe if you did anything fun with your kids, they’d make noise too.",
  giraffe:{ o:"When you said you heard my class through the wall and called it zoo day,", f:"I felt embarrassed", n:"because I want respect and to work well with you as a neighbour", r:"Would you be willing to knock on my door or tell me privately if the noise is disturbing your lessons?" },
  say:"Linda, when you mentioned the zoo day in front of everyone, I felt embarrassed. I do want to be a good neighbour. If the noise gets in the way of your lessons, could you pop over and let me know privately?",
  empathy:"Were you feeling distracted and needing some quiet to teach?",
  tip:"Separate the sting of the delivery from the real request underneath; respond to both." },
{ id:"school-10", title:"Student swears at teacher", context:"When asked to put his phone away, 14-year-old Jayden says, “This is f—ing stupid,” loudly enough for the whole class to hear.", who:"teen", level:3,
  jackal:"How dare you speak to me like that! Get out of my classroom!",
  giraffe:{ o:"When I asked you to put your phone away, you swore loudly.", f:"I feel shocked", n:"because I need respect and a safe learning space for everyone", r:"Would you be willing to take a few minutes at the back table and then talk with me after class?" },
  say:"Jayden, that word was really loud. I want this room to be respectful for everyone. Take a few minutes at the back table, and let’s talk after class.",
  empathy:"Are you feeling frustrated or embarrassed and needing some say in what happens to you?",
  tip:"Keep your voice low and slow; the calmer you are, the faster a student’s nervous system can settle." },
{ id:"school-11", title:"“My child is bored”", context:"At pickup, a mother, Mrs. Ahmed, tells the teacher her daughter Layla says class is “too easy and boring.”", who:"adult", level:2,
  jackal:"Well, maybe Layla isn’t as advanced as you think.",
  giraffe:{ o:"You’re telling me Layla has been saying class is too easy.", f:"I’m curious and want to understand", n:"because I want her to feel challenged and engaged", r:"Could we set up a short meeting next week so I can share her work and hear more from you?" },
  say:"Thank you for telling me. I want Layla to feel challenged and excited. Could we meet next week? I’ll bring some of her work and I’d love to hear what she says at home.",
  empathy:"Are you worried that Layla isn’t growing as much as she could and wanting to advocate for her?",
  tip:"Treat parents as experts on their own child; curiosity turns a complaint into a partnership." },
{ id:"school-12", title:"Copied homework", context:"Two students, Aiden and Sara, hand in essays with identical paragraphs.", who:"teen", level:2,
  jackal:"You’re both cheaters, and you’re both getting a zero.",
  giraffe:{ o:"Your essays have three paragraphs that are word-for-word the same.", f:"I feel disappointed", n:"because I value honesty and want to see your own thinking", r:"Would you each be willing to meet me at lunch to talk about what happened?" },
  say:"Aiden, Sara, three paragraphs in your essays are word-for-word the same. I’m disappointed, because I really want to see your own thinking. Can I meet each of you at lunch to understand what happened?",
  empathy:"Were you feeling pressured for time and worried about your grades?",
  tip:"Talk to each student separately; you’ll hear more honesty without an audience." },
{ id:"school-13", title:"Won’t clean up blocks", context:"In kindergarten, five-year-old Lucia keeps building with blocks after the tidy-up song has finished.", who:"child", level:1,
  jackal:"Lucia, you never listen! Everyone else is waiting for you.",
  giraffe:{ o:"The tidy-up song is over and the blocks are still out.", f:"I feel a bit rushed", n:"because we need the carpet clear for story time", r:"Would you like to put the blue blocks away or the red ones?" },
  say:"Lucia, the tidy-up song finished and your tower’s still up! We need the carpet for story time. Do you want to put away the blue blocks or the red ones?",
  empathy:"Are you feeling proud of your tower and wanting more time to finish it?",
  tip:"Offering two acceptable options gives a young child a sense of control while the task still gets done." },
{ id:"school-14", title:"Classroom meltdown", context:"Eight-year-old Oliver throws his pencil case across the room and screams after getting a worksheet wrong.", who:"child", level:3,
  jackal:"That’s it! Go to the principal’s office right now!",
  giraffe:{ o:"Your pencil case flew across the room and you’re screaming.", f:"I feel worried", n:"I need you and everyone else to be safe", r:"Can you come sit in the quiet corner with me and breathe for a bit?" },
  say:"Oliver, you seem really upset. I need everyone safe. Come sit in the quiet corner with me — we’ll breathe for a bit, and then we’ll figure out the worksheet together.",
  empathy:"Are you feeling really frustrated because you wanted to get it right?",
  tip:"Calm first, teach later; a child in the middle of a meltdown can’t learn or reason until they feel safe." },
{ id:"school-15", title:"Teacher workload to principal", context:"Teacher Mr. Dlamini has been asked to run a new after-school club on top of a full timetable.", who:"adult", level:2,
  jackal:"You always dump everything on us. Do you have any idea how much we do?",
  giraffe:{ o:"I’m teaching five classes and running two clubs, and now I’m asked to add a third.", f:"I feel overwhelmed", n:"because I need sustainability so I can teach well", r:"Could we look together at which commitment I could drop if I take this on?" },
  say:"I’m teaching five classes and running two clubs already, and adding a third leaves me overwhelmed. I want to keep teaching well. Could we look together at what I could drop if I take this on?",
  empathy:"Are you feeling pressure to provide more for students with limited staff?",
  tip:"Offer a trade-off instead of a flat no; it shows you share the goal." },
{ id:"school-16", title:"Disputing a grade", context:"University student Nadia believes her essay was marked down for a point she actually addressed on page four.", who:"adult", level:2,
  jackal:"You obviously didn’t even read my essay properly.",
  giraffe:{ o:"The feedback says I didn’t address counterarguments, and I discussed them on page four.", f:"I feel confused", n:"because I value fairness and want to understand the marking", r:"Would you be willing to look at page four with me during office hours this week?" },
  say:"Hi Professor Lee, the feedback says I didn’t address counterarguments, but I think I did on page four. I’m a bit confused. Could we look at it together during office hours this week?",
  empathy:"Are you marking a lot of papers and needing some understanding about your time?",
  tip:"Point to exact evidence and stay curious; “help me understand” works better than “you were wrong.”" },
{ id:"school-17", title:"“You can’t play with us”", context:"At recess, seven-year-old Ava tells new classmate Priyanka, “You can’t play, this game is only for us.”", who:"child", level:1,
  jackal:"Ava, that’s mean. You’re being a bully.",
  giraffe:{ o:"I heard you tell Priyanka she can’t play.", f:"I feel sad", n:"because I want everyone in our class to belong", r:"Can you think of a job Priyanka could have in your game?" },
  say:"Ava, I heard you tell Priyanka she can’t play. That makes me sad, because I want everyone in our class to belong. What job could she have in your game?",
  empathy:"Are you worried the game will change and wanting it to stay fun the way it is?",
  tip:"Some schools use a “you can’t say you can’t play” rule, an idea from teacher Vivian Paley; it builds belonging." },
{ id:"school-18", title:"Phone out in class", context:"Seventeen-year-old Marco is scrolling his phone under the desk during a lecture.", who:"teen", level:1,
  jackal:"Give me that phone. You’re addicted.",
  giraffe:{ o:"I see your phone out under the desk.", f:"I feel distracted", n:"because I want your focus and attention for this part", r:"Would you be willing to put it in your bag until the bell?" },
  say:"Marco, I see the phone under the desk. It pulls my focus too. Can you pop it in your bag till the bell? Thanks.",
  empathy:"Are you waiting on something important or feeling bored and needing stimulation?",
  tip:"A quiet word or a gesture often works better than calling a student out in front of peers." },
{ id:"school-19", title:"Parent never responds", context:"Teacher Ms. Rossi has emailed and called Kai’s dad three times about missing assignments with no reply.", who:"adult", level:2,
  jackal:"I guess you don’t care about your son’s education.",
  giraffe:{ o:"I’ve reached out three times this month about Kai’s missing assignments.", f:"I feel concerned", n:"because I want to work together to support Kai", r:"Would a five-minute call at a time that suits you work, maybe this Saturday morning?" },
  say:"Hello Mr. Tanaka, I’ve reached out a few times about Kai’s missing work, and I’m a bit concerned. I’d love to team up for him. Would a quick five-minute call this Saturday morning suit you?",
  empathy:"Is it possible you’re juggling long hours and feeling stretched?",
  tip:"Assume barriers before indifference: shift work, language, or past bad experiences with schools." },
{ id:"school-20", title:"After a terrible lesson", context:"First-year teacher Leah’s lesson fell apart today and she’s replaying it at home.", who:"self", level:2,
  jackal:"I’m a useless teacher. They don’t respect me. I should quit.",
  giraffe:{ o:"In third period, the class talked over me for most of the lesson.", f:"I feel discouraged and drained", n:"I need support and a sense of growth", r:"Can I ask a mentor to observe next week and choose one thing to try tomorrow?" },
  say:"Third period was hard, and I feel drained. I care a lot about doing this well. Tomorrow I’ll try one new thing, and I’ll ask Mr. Chen if he can observe next week.",
  empathy:"Am I feeling lonely in this and needing encouragement from people who’ve been there?",
  tip:"Swap “I’m a bad teacher” for “That lesson didn’t work yet”; self-compassion helps you learn faster." },
{ id:"school-21", title:"Class was rude to the substitute", context:"A substitute’s note says the whole Year 8 class talked, threw paper and ignored instructions yesterday.", who:"group", level:2,
  jackal:"I’m ashamed of all of you. You’re the worst class I’ve ever had.",
  giraffe:{ o:"The substitute wrote that people threw paper and talked over her yesterday.", f:"I feel disappointed", n:"because I want guests in our room to be treated with respect", r:"Would you all be willing to help write a thank-you or apology note to her today?" },
  say:"Folks, Ms. Grant’s note says there was paper-throwing and talking over her. I’m disappointed, because I want everyone in our room treated with respect. Let’s talk about what happened, and then write her a note together.",
  empathy:"Were some of you feeling unsettled with the change and wanting some fun or predictability?",
  tip:"Invite the class to problem-solve in a circle; shared responsibility works better than group punishment." },
{ id:"school-22", title:"New student alone", context:"Ten-year-old Tomás, who just moved from another country, has eaten lunch alone every day this week.", who:"child", level:1,
  jackal:"Go sit with someone. You need to make an effort.",
  giraffe:{ o:"I’ve noticed you’ve been eating lunch by yourself this week.", f:"I feel caring and a little concerned", n:"because I want you to feel welcome here", r:"Would you like me to introduce you to two classmates who also love football?" },
  say:"Tomás, I’ve seen you eating lunch on your own this week. I really want you to feel welcome here. Would you like to meet two kids who love football too?",
  empathy:"Are you feeling a bit lonely and wanting to find friends?",
  tip:"Give new students a buddy and a classroom job; belonging grows through contribution." }
]}
,
{ id:"work", name:"Workplace", icon:"💼", hue:210, blurb:"Handle deadlines, feedback, credit and conflict at work without losing your cool or your voice.", cases:[
{ id:"work-01", title:"Colleague took my credit", context:"In the team meeting, Ryan presented the customer dashboard idea Leila had shared with him privately as his own.", who:"peer", level:3,
  jackal:"You stole my idea, Ryan. You’re a total snake.",
  giraffe:{ o:"In today’s meeting you presented the dashboard idea I shared with you on Tuesday without mentioning me.", f:"I felt shocked and hurt", n:"because I need acknowledgement and trust between us", r:"Would you be willing to send a note to the team today clarifying that we developed it together?" },
  say:"Ryan, in the meeting you presented the dashboard idea I shared with you Tuesday, and my name didn’t come up. I felt pretty hurt. Could you send the team a quick note today saying it came from both of us?",
  empathy:"Were you excited about the idea and wanting to be seen as contributing too?",
  tip:"Talk privately and soon, before resentment builds; document your ideas in writing going forward." },
{ id:"work-02", title:"Last-minute deadline", context:"At 4 p.m. on Friday, manager Diane asks Arjun to finish a 20-page report by Monday 9 a.m.", who:"adult", level:2,
  jackal:"Are you serious? You always do this to us at the last minute.",
  giraffe:{ o:"It’s 4 p.m. Friday and the report is due Monday at 9.", f:"I’m feeling stressed", n:"because I need rest this weekend and want to do quality work", r:"Could we agree on the three most important sections for Monday and the rest for Wednesday?" },
  say:"Diane, I want to get this right, and with it landing at 4 on a Friday I’m feeling stressed about the weekend. Could we pick the three key sections for Monday and do the rest by Wednesday?",
  empathy:"Are you under pressure from leadership and needing reliability from the team?",
  tip:"Negotiate scope, not just time; ask what matters most." },
{ id:"work-03", title:"Interrupted in meetings", context:"For the third meeting in a row, colleague Greg talks over Ana before she finishes her point.", who:"peer", level:2,
  jackal:"Can you let someone else talk for once? You love the sound of your own voice.",
  giraffe:{ o:"In the last three meetings, you started speaking before I’d finished my point.", f:"I feel frustrated", n:"because I want to contribute and be heard", r:"Would you be willing to let me finish before jumping in?" },
  say:"Greg, I’ve noticed in the last few meetings you jump in before I’ve finished. I get frustrated because I want to fully share my ideas. Could you let me finish first?",
  empathy:"Are you feeling enthusiastic and worried your idea will get lost?",
  tip:"In the moment, a calm “I’d like to finish my thought” is enough; save the bigger conversation for later." },
{ id:"work-04", title:"Slow replies remote", context:"Working remotely, teammate Sven often takes two days to reply to messages that block Mei-Ling’s work.", who:"peer", level:1,
  jackal:"Do you ever check your messages? I’m stuck because of you.",
  giraffe:{ o:"My last two questions to you took about two days to get a reply.", f:"I feel stuck and anxious", n:"because I need to keep my work moving", r:"Could we agree that you’ll reply to blocking questions within a day, even if it’s just to say ‘looking into it’?" },
  say:"Hi Sven! My last couple of questions took about two days to hear back on, and I got stuck. Could we agree on a one-day reply for blocking questions, even just a quick “on it”?",
  empathy:"Are you drowning in notifications and needing a clearer way to prioritize?",
  tip:"Agree on team norms for response times and tag urgent messages clearly." },
{ id:"work-05", title:"Report missing deadlines", context:"Manager Kwame’s direct report, Jenna, has missed three sprint deadlines in a row.", who:"adult", level:2,
  jackal:"Jenna, your performance is unacceptable. Shape up or there will be consequences.",
  giraffe:{ o:"The last three sprint tasks you owned were delivered after the deadline.", f:"I’m concerned", n:"because I need predictability for the team and want to support you", r:"Could you walk me through what got in the way, so we can plan for the next sprint together?" },
  say:"Jenna, the last three sprint tasks came in after the deadline. I’m concerned and I want to help. Can you walk me through what got in the way so we can plan the next one together?",
  empathy:"Are you feeling overloaded or unclear on priorities and needing support?",
  tip:"Kim Scott’s Radical Candor: care personally while challenging directly." },
{ id:"work-06", title:"Receiving harsh feedback", context:"In a review, Bruno’s boss says his presentation was “sloppy and unprofessional.”", who:"adult", level:2,
  jackal:"That’s ridiculous. You don’t appreciate anything I do.",
  giraffe:{ o:"You said my presentation was sloppy and unprofessional.", f:"I feel surprised and a bit stung", n:"because I want to understand and improve", r:"Could you give me two specific examples of what you’d like done differently?" },
  say:"That’s tough to hear, and I want to improve. Could you share two specific things in the presentation you’d like done differently?",
  empathy:"Are you worried about how our team comes across to the client?",
  tip:"Translate judgments into observations by asking for specifics; it turns criticism into usable information." },
{ id:"work-07", title:"Announcing layoffs", context:"Department head Monique must tell her team of twelve that four positions are being cut.", who:"group", level:3,
  jackal:"It’s not my decision, so there’s no point complaining to me.",
  giraffe:{ o:"The company has decided to cut four positions in our department.", f:"I feel heavy and sad sharing this", n:"because I care about each of you and want honesty and clarity", r:"Will you come to one-on-one meetings with me this afternoon so I can answer your questions individually?" },
  say:"I have hard news. The company has decided to cut four positions in our team. I feel heavy telling you this, because I care about each of you. I’ll meet everyone one-on-one this afternoon to answer your questions.",
  empathy:"Are you feeling scared and wanting security and transparency about what happens next?",
  tip:"Be clear and human; don’t hide behind jargon, and give people time and space to react." },
{ id:"work-08", title:"Client scope creep", context:"Client Mr. Ferreira keeps asking designer Yara for “just one more small change” beyond the agreed contract.", who:"adult", level:2,
  jackal:"This isn’t what you paid for. You can’t keep taking advantage.",
  giraffe:{ o:"This is the fifth change request since we agreed on the final design.", f:"I feel uneasy", n:"because I need fairness and clarity in our agreement", r:"Would you like me to send a quote for these extra changes so we can keep going?" },
  say:"Mr. Ferreira, I’m glad you’re invested in getting it right. This is the fifth change since we signed off, and I want to stay fair to both of us. Shall I send a quote for these extras so we can keep moving?",
  empathy:"Are you wanting the result to be perfect for your launch?",
  tip:"Name what’s in scope early; a friendly change-order process prevents resentment." },
{ id:"work-09", title:"Loud phone calls", context:"In the open office, Tariq takes long speakerphone calls at his desk next to Olivia.", who:"peer", level:1,
  jackal:"Some of us are trying to work, you know.",
  giraffe:{ o:"When you take calls on speaker at your desk,", f:"I feel distracted", n:"because I need focus for my writing", r:"Would you be willing to use headphones or a booth for longer calls?" },
  say:"Hey Tariq, when you take calls on speaker I lose my focus on my writing. Would you mind using headphones or grabbing a booth for the longer ones?",
  empathy:"Are you finding it hard to hear on headphones or needing to stay at your screen?",
  tip:"Assume they haven’t noticed; most people genuinely don’t realize how much sound carries." },
{ id:"work-10", title:"Boss emails at night", context:"Manager Paul regularly sends Simone emails at 10 p.m. and expects replies before morning.", who:"adult", level:2,
  jackal:"I have a life, Paul. Stop texting me in the middle of the night.",
  giraffe:{ o:"I’ve had emails from you after 10 p.m. most nights this week asking for replies before 8.", f:"I feel tense and tired", n:"because I need rest to work well", r:"Could we agree that anything after 7 p.m. waits until morning unless it’s marked urgent?" },
  say:"Paul, I’ve been getting late-night emails asking for replies first thing, and I’m feeling run-down. I do my best work when I’ve rested. Could anything after 7 wait for morning unless it’s flagged urgent?",
  empathy:"Do you work best late and want to capture ideas before you forget?",
  tip:"Propose a clear rule rather than complaining about the pattern; suggest scheduled send." },
{ id:"work-11", title:"Asking for a raise", context:"After two years and taking on team-lead duties, Ifeoma wants to ask her manager for a raise.", who:"adult", level:2,
  jackal:"I’m clearly underpaid and you’ve been taking advantage of me.",
  giraffe:{ o:"Over the past year I’ve led a team of four and delivered both major launches.", f:"I feel proud and hopeful", n:"because I value fair recognition", r:"Would you be willing to discuss a salary adjustment to reflect this role at our next one-on-one?" },
  say:"Over the past year I’ve led a team of four and shipped both launches. I’m proud of that work and want my pay to reflect the role. Can we discuss a salary adjustment at our next one-on-one?",
  empathy:"Are you working within budget limits and wanting to keep things fair across the team?",
  tip:"Bring facts and market data, and focus on contribution rather than personal need." },
{ id:"work-12", title:"Meetings always run over", context:"The weekly team meeting scheduled for 30 minutes regularly runs to an hour.", who:"group", level:1,
  jackal:"These meetings are a waste of everyone’s time.",
  giraffe:{ o:"Our last four meetings went 25 to 30 minutes past the scheduled half hour.", f:"I feel anxious", n:"because I need to manage my time and other commitments", r:"Would we be willing to try an agenda with timings and a timekeeper next week?" },
  say:"I noticed our last four meetings ran almost an hour instead of thirty minutes, and I get anxious about what I’m missing. Could we try a timed agenda and a timekeeper next week?",
  empathy:"Are there things that really need discussing, and people wanting space to be heard?",
  tip:"Propose an experiment rather than a permanent rule; it’s easier for a group to say yes." },
{ id:"work-13", title:"Missed handoff", context:"Colleague Hannah forgot to pass on client notes, so Luis walked into a call unprepared.", who:"peer", level:2,
  jackal:"Thanks a lot, Hannah. You made me look like an idiot.",
  giraffe:{ o:"I didn’t get the client notes before the 2 p.m. call.", f:"I felt embarrassed and frustrated", n:"because I need reliable handoffs to do my job well", r:"Could we set up a shared checklist for handoffs from now on?" },
  say:"Hannah, I didn’t get the notes before the 2 p.m. call and went in blind — pretty embarrassing. Could we set up a shared checklist for handoffs so it doesn’t happen to either of us?",
  empathy:"Were you swamped today and wishing there were a simpler system?",
  tip:"Focus on fixing the system, not blaming the person." },
{ id:"work-14", title:"Micromanaged", context:"Manager Elaine asks Jun for hourly status updates and rewrites his emails before they go out.", who:"adult", level:2,
  jackal:"Do you think I’m incompetent? Back off and let me do my job.",
  giraffe:{ o:"This week you’ve asked for hourly updates and edited four of my client emails.", f:"I feel discouraged", n:"because I need trust and autonomy to grow", r:"Could we try daily check-ins instead for two weeks and review how it goes?" },
  say:"Elaine, I want you to feel confident in my work. With hourly updates and edits to my emails, I feel discouraged. Could we try a daily check-in for two weeks and see how it goes?",
  empathy:"Are you feeling worried about results and needing confidence that things are on track?",
  tip:"Offer a structured alternative that still meets your manager’s need for reassurance." },
{ id:"work-15", title:"Furious customer", context:"In a phone shop, customer Mr. Bakr shouts at staff member Elif that her company is “a bunch of thieves” over a billing error.", who:"adult", level:3,
  jackal:"Sir, there’s no need to shout. It’s not my fault.",
  giraffe:{ o:"You’ve been charged twice for this month.", f:"I can see you’re really angry, and I want to help", n:"because you need fairness and your money back", r:"Can I take your account number and start the refund right now?" },
  say:"You were charged twice — I’d be angry too. I want to sort this out for you. Can I grab your account number and start the refund right now?",
  empathy:"Are you feeling furious because you need to trust that you’re being treated fairly?",
  tip:"Empathize before explaining; people can’t hear solutions until they feel heard." },
{ id:"work-16", title:"Offensive joke", context:"At lunch, colleague Mark makes a joke that stereotypes women in engineering, and a few people laugh.", who:"peer", level:3,
  jackal:"Wow, Mark, you’re such a sexist dinosaur.",
  giraffe:{ o:"When you made that joke about women engineers,", f:"I felt uncomfortable", n:"because I want everyone here to be respected", r:"Would you be willing to skip jokes like that from now on?" },
  say:"Mark, that joke about women engineers didn’t sit well with me. I want everyone here to feel respected. Could you leave jokes like that out going forward?",
  empathy:"Were you trying to lighten the mood and connect with the group?",
  tip:"Speaking up briefly and calmly in the moment signals the norm to everyone listening." },
{ id:"work-17", title:"Overloaded after layoffs", context:"After two colleagues were laid off, Sunita has absorbed their work and is working 60-hour weeks.", who:"adult", level:3,
  jackal:"You fired people and expected me to do three jobs. This is exploitation.",
  giraffe:{ o:"Since the restructure, I’ve been working about 60 hours a week covering three roles.", f:"I’m exhausted and worried", n:"because I need sustainability and my health", r:"Can we meet this week to agree which projects pause until we have more staff?" },
  say:"Since the restructure I’ve been covering three roles at around 60 hours a week, and I’m exhausted. I want to keep doing good work. Can we meet this week to decide which projects pause until we’re staffed up?",
  empathy:"Are you under pressure to deliver with fewer resources and needing support too?",
  tip:"Make the workload visible with a list; let your manager choose the priorities." },
{ id:"work-18", title:"Saying no to a project", context:"Colleague Fiona asks Ahmed to join her committee on top of his full workload.", who:"peer", level:2,
  jackal:"Why does everyone think I have time for their stuff?",
  giraffe:{ o:"You asked me to join the committee, and I’m already at capacity this quarter.", f:"I feel torn", n:"because I want to support you and also keep my commitments", r:"Would it help if I reviewed your proposal once instead of joining?" },
  say:"I’d love to support it, Fiona, and I’m maxed out this quarter. Would it help if I reviewed your proposal once instead of joining the committee?",
  empathy:"Are you looking for support and wanting the committee to succeed?",
  tip:"Every no is a yes to something else; offering a smaller yes keeps the relationship warm." },
{ id:"work-19", title:"Ignored chat message", context:"Bea asked teammate Carlos a yes-or-no question in chat three days ago and got no answer.", who:"peer", level:1,
  jackal:"Hello?? Are you ignoring me?",
  giraffe:{ o:"I sent you a question on Monday and haven’t heard back.", f:"I feel a bit uncertain", n:"because I need clarity to move forward", r:"Could you let me know yes or no by end of day?" },
  say:"Hi Carlos, just bumping my Monday question. I need an answer to move ahead — could you let me know yes or no by end of day? Thanks!",
  empathy:"Did it get buried in a busy week?",
  tip:"A friendly follow-up with a clear deadline usually works better than a pointed one." },
{ id:"work-20", title:"Botched presentation", context:"Nam froze during a presentation to senior leadership and lost his place twice.", who:"self", level:1,
  jackal:"I humiliated myself. Everyone thinks I’m incompetent now.",
  giraffe:{ o:"I lost my place twice during the presentation.", f:"I feel embarrassed and disappointed", n:"I need competence and self-acceptance", r:"Can I write down two things that went well and one thing to practise for next time?" },
  say:"I lost my place twice, and I’m disappointed because I care about doing well. I’ll write down two things that went well and one thing I’ll rehearse next time.",
  empathy:"Am I feeling nervous because I want to be respected by leadership?",
  tip:"Other people remember your mistakes far less than you do; focus on what you’ll practise." },
{ id:"work-21", title:"Daily venting colleague", context:"Every morning, colleague Dana spends 30 minutes at Priya’s desk complaining about her ex.", who:"peer", level:2,
  jackal:"Dana, I’m not your therapist.",
  giraffe:{ o:"Most mornings this week we’ve talked about your ex for around half an hour.", f:"I feel caring and also stressed", n:"because I want to support you and need time to focus", r:"Would you be up for grabbing lunch on Friday to talk, and keeping mornings for work?" },
  say:"Dana, I care about you and I can see this is really hard. Most mornings we’ve talked for half an hour and I’m falling behind. Could we grab lunch Friday to talk and keep mornings for work?",
  empathy:"Are you feeling lonely and needing someone to listen?",
  tip:"You can care and still have limits; offer a time that works for you." },
{ id:"work-22", title:"Unequal hybrid rules", context:"Gabriel is required to come into the office five days a week while others on his team work from home three days.", who:"adult", level:2,
  jackal:"This is favouritism. Why do they get special treatment?",
  giraffe:{ o:"I’m in the office five days a week while most of the team is in two.", f:"I feel confused and a bit resentful", n:"because I value fairness and flexibility", r:"Could you explain the reasons, and would you consider two remote days for me as a trial?" },
  say:"I’ve noticed I’m in five days while most of the team does two. I feel confused and a bit resentful. Could you help me understand the reasoning, and would you consider a two-day remote trial for me?",
  empathy:"Are there needs for coverage or support that I might not know about?",
  tip:"Ask for the reasoning first; there may be a need you can meet another way." }
]}
,
{ id:"love", name:"Romantic Relationships", icon:"💞", hue:340, blurb:"Turn the everyday frictions of love into honest conversations that bring you closer.", cases:[
{ id:"love-01", title:"Who does the chores", context:"Sam has cleaned the kitchen every night this week while partner Jordan watched TV.", who:"adult", level:1,
  jackal:"I’m not your maid. You never lift a finger around here.",
  giraffe:{ o:"I’ve cleaned the kitchen every night this week.", f:"I’m feeling tired and a little resentful", n:"because I need partnership and balance at home", r:"Would you be willing to take kitchen duty Monday, Wednesday and Friday?" },
  say:"Babe, I’ve done the kitchen every night this week, and I’m starting to feel tired and resentful. I want us to feel like a team. Could you take Monday, Wednesday and Friday?",
  empathy:"Are you feeling drained after work and needing some downtime too?",
  tip:"Write down the actual split of chores; invisible work often goes unnoticed." },
{ id:"love-02", title:"Phone at dinner", context:"At dinner, Lucas scrolls Instagram while Camila tells him about her day.", who:"adult", level:1,
  jackal:"You care more about your phone than you do about me.",
  giraffe:{ o:"While I was telling you about my day, you were scrolling your phone.", f:"I felt lonely", n:"because I need connection and attention with you", r:"Would you be willing to put our phones in the basket during dinner?" },
  say:"Hey, while I was talking about my day you were on your phone, and I felt kind of lonely. I miss you. Could we put our phones in the basket during dinner?",
  empathy:"Were you unwinding after a stressful day and needing a little escape?",
  tip:"Make the request about both of you, not just them; shared rules feel less like blame." },
{ id:"love-03", title:"Different sex drives", context:"Elena and Marcus haven’t been intimate in two months, and Elena feels rejected whenever she initiates.", who:"adult", level:3,
  jackal:"You’re never in the mood. Do you even find me attractive anymore?",
  giraffe:{ o:"It’s been about two months since we were intimate, and the last few times I reached out you said you were tired.", f:"I feel sad and a bit insecure", n:"because I need closeness and to feel desired", r:"Would you be willing to talk about this together this weekend, without any pressure?" },
  say:"I miss being close with you. The last few times I reached out you were tired, and I’ve started feeling insecure. Could we talk about it this weekend, no pressure — I just want to understand each other?",
  empathy:"Are you feeling exhausted or stressed and needing rest and understanding?",
  tip:"Talk about intimacy outside the bedroom, at a calm time, with curiosity rather than accusation." },
{ id:"love-04", title:"Whose family for holidays", context:"Ji-woo wants to spend the holidays with her family in Seoul, and her husband Kevin wants to go to his parents’ in Ohio.", who:"adult", level:2,
  jackal:"Your family always comes first. Mine never matters.",
  giraffe:{ o:"We’ve spent the last two holidays with your parents.", f:"I feel homesick and sad", n:"because I need connection with my family and fairness", r:"Would you be willing to go to Seoul this year and Ohio next?" },
  say:"We’ve been to your parents’ the last two years, and I’m really homesick. I want us both to feel connected to our families. Could we do Seoul this year and Ohio next?",
  empathy:"Are you worried about letting your parents down and wanting them to feel loved?",
  tip:"Look for creative strategies; there’s usually more than one way to meet both needs." },
{ id:"love-05", title:"Texts from an ex", context:"Adebayo notices his girlfriend Tolu texting with her ex late at night several times this week.", who:"adult", level:3,
  jackal:"Why are you still talking to him? Are you cheating on me?",
  giraffe:{ o:"I’ve seen you texting your ex late at night a few times this week.", f:"I feel anxious and insecure", n:"because I need trust and reassurance in our relationship", r:"Would you be willing to tell me what’s going on with him?" },
  say:"Tolu, I’ve noticed you texting your ex late at night a few times this week, and I’m feeling anxious. I need some reassurance. Can you tell me what’s going on?",
  empathy:"Is there something you’re dealing with and needing support or a friend about?",
  tip:"Own your jealousy as your feeling; ask rather than accuse." },
{ id:"love-06", title:"Big purchase without asking", context:"Nikhil bought a $1,500 gaming PC without discussing it with his wife Anjali.", who:"adult", level:2,
  jackal:"How could you be so irresponsible? We’re saving for a house!",
  giraffe:{ o:"You bought the $1,500 computer without us talking first.", f:"I feel worried and upset", n:"because I need us to make big financial decisions together", r:"Could we agree to discuss any purchase over $200 before buying?" },
  say:"Nikhil, the $1,500 computer surprised me. I’m worried because we’re saving for the house, and I want us making big money decisions together. Can we agree to talk about anything over $200 first?",
  empathy:"Were you craving something just for you after a stressful few months?",
  tip:"Set a shared “check-in threshold” for spending; it prevents surprises." },
{ id:"love-07", title:"Last-minute cancel", context:"An hour before their dinner reservation, Aiden texts Maya that he has to work late.", who:"adult", level:1,
  jackal:"Wow, I guess work is always more important than me.",
  giraffe:{ o:"You texted an hour before dinner to say you’re working late.", f:"I feel disappointed", n:"because I was looking forward to time together", r:"Could we rebook for Thursday?" },
  say:"Aw, I’m so disappointed — I was really looking forward to tonight. Can we rebook for Thursday?",
  empathy:"Are you feeling stressed and torn between work and us?",
  tip:"Express disappointment without punishment; then make a concrete plan." },
{ id:"love-08", title:"Ending the relationship", context:"After a year together, Clara has realized she wants to break up with Theo.", who:"adult", level:3,
  jackal:"It’s you, not me. You’re just not enough for me.",
  giraffe:{ o:"We’ve talked many times about wanting different futures.", f:"I feel sad and certain", n:"because I need honesty and to live in line with what I want", r:"Would you be willing to talk about how we end this kindly?" },
  say:"Theo, this is really hard to say. We’ve talked so many times about wanting different futures, and I’ve realized I need to end our relationship. I’m sad, and I care about you. Can we talk about how to do this kindly?",
  empathy:"Are you feeling shocked and hurt, and needing understanding and time?",
  tip:"Be clear and kind; vague breakups prolong the pain." },
{ id:"love-09", title:"Late with no text", context:"Lucía’s partner Ben came home two hours late without texting.", who:"adult", level:1,
  jackal:"Where were you? You’re so inconsiderate!",
  giraffe:{ o:"You came home two hours later than you said and I didn’t hear from you.", f:"I was worried", n:"because I need to know you’re safe", r:"Would you text me if you’re going to be more than half an hour late?" },
  say:"I was really worried — two hours and no text. I need to know you’re okay. Could you text me if you’re running more than half an hour late?",
  empathy:"Did something come up and your phone died?",
  tip:"Underneath anger is often fear; lead with the fear." },
{ id:"love-10", title:"Criticized in front of friends", context:"At a dinner party, Sophie joked to friends that her husband Raj “can’t even boil an egg.”", who:"adult", level:2,
  jackal:"Thanks for humiliating me in front of everyone.",
  giraffe:{ o:"When you said I can’t boil an egg in front of our friends,", f:"I felt embarrassed", n:"because I need respect from you in front of others", r:"Would you be willing to keep teasing like that between us?" },
  say:"When you said I can’t boil an egg in front of everyone, I felt embarrassed. I need us to have each other’s backs in public. Could you keep that kind of teasing just between us?",
  empathy:"Were you trying to be funny and connect with friends?",
  tip:"Raise it privately afterwards, not in front of others." },
{ id:"love-11", title:"Wanting quality time", context:"Natasha and Ivan haven’t been on a date in three months.", who:"adult", level:2,
  jackal:"We never do anything fun anymore. You’re so boring.",
  giraffe:{ o:"We haven’t been on a date in three months.", f:"I feel sad", n:"because I need fun and connection with you", r:"Would you be up for a date night every second Friday?" },
  say:"I realized we haven’t been on a date in three months, and I miss us. Would you be up for a date every second Friday? I’ll plan the first one!",
  empathy:"Are you feeling tired and stretched too, and wanting more ease?",
  tip:"John Gottman’s research highlights small, regular moments of connection as key to lasting relationships." },
{ id:"love-12", title:"Forgotten anniversary", context:"Malik forgot his and Amina’s fifth wedding anniversary.", who:"adult", level:2,
  jackal:"You don’t even care about us. How could you forget?",
  giraffe:{ o:"Yesterday was our anniversary and it wasn’t mentioned.", f:"I feel hurt", n:"because I need to feel valued and remembered", r:"Would you plan something with me this weekend to celebrate?" },
  say:"Yesterday was our anniversary, and when it passed without a word I felt hurt. I want to feel celebrated with you. Can we plan something this weekend?",
  empathy:"Are you feeling bad about it and wanting to make it up?",
  tip:"Shared calendars help; but the conversation about what anniversaries mean matters more." },
{ id:"love-13", title:"Advice instead of listening", context:"When Priya talks about a conflict at work, her partner Daniel immediately tells her what to do.", who:"adult", level:1,
  jackal:"You never listen. You just want to fix everything.",
  giraffe:{ o:"When I told you about my boss, you started giving solutions right away.", f:"I felt frustrated", n:"because I need empathy and to be heard first", r:"Would you be willing to just listen for a few minutes before offering advice?" },
  say:"I know you want to help, love. When I talk about work, I mostly need you to listen first. Could you just hear me out for a few minutes before suggesting things?",
  empathy:"Do you care about me and want to help me feel better?",
  tip:"Try asking “Do you want empathy or ideas?” before responding." },
{ id:"love-14", title:"Cleanliness clash", context:"Since moving in together, Felix leaves clothes on the floor, which bothers his tidy partner Hugo.", who:"adult", level:2,
  jackal:"You’re such a slob. Were you raised in a barn?",
  giraffe:{ o:"There are clothes on the bedroom floor most mornings.", f:"I feel irritated", n:"because I need order in our shared space", r:"Would you be willing to use the laundry basket each night?" },
  say:"Felix, there are clothes on the floor most mornings, and it irritates me. Having order really helps me relax. Could you toss them in the basket each night?",
  empathy:"Are you comfortable with more mess and wanting to feel relaxed at home too?",
  tip:"Different tidiness standards are normal; negotiate zones or routines." },
{ id:"love-15", title:"Drinking at parties", context:"At the last three parties, Javier drank heavily and his partner Laura had to drive him home.", who:"adult", level:3,
  jackal:"You’re an embarrassment when you drink. You have a problem.",
  giraffe:{ o:"At the last three parties, I drove you home after you’d had a lot to drink.", f:"I feel worried and frustrated", n:"because I need safety and enjoyment for both of us", r:"Would you be willing to talk about this tomorrow when we’re both rested?" },
  say:"Javi, I’ve driven you home after the last three parties, and I’m worried and frustrated. I want us both to be safe and enjoy ourselves. Can we talk about this tomorrow when we’re rested?",
  empathy:"Are you feeling anxious socially and needing ease?",
  tip:"Never try to have this conversation while someone is drunk." },
{ id:"love-16", title:"Always working late", context:"For the past month, Sarah has worked until 9 p.m. most nights, and her husband Tom eats alone.", who:"adult", level:2,
  jackal:"You’re married to your job, not me.",
  giraffe:{ o:"You’ve worked until nine most nights this month.", f:"I feel lonely", n:"because I need connection with you", r:"Could we commit to two dinners together each week?" },
  say:"I’ve eaten alone most nights this month, and I feel lonely. I miss you. Could we commit to two dinners together each week?",
  empathy:"Are you stressed about work and needing support?",
  tip:"Ask for a specific number rather than “more time.”" },
{ id:"love-17", title:"Kids or no kids", context:"After four years together, Rachel wants children and her partner Owen is unsure.", who:"adult", level:3,
  jackal:"If you don’t want kids, you’ve wasted my time.",
  giraffe:{ o:"When I mention having kids, you change the subject.", f:"I feel anxious", n:"because I need clarity about our future", r:"Would you be willing to talk honestly about this on Sunday?" },
  say:"Owen, I’ve noticed you change the subject when I bring up kids. I’m anxious because I need clarity about our future. Could we talk honestly about it on Sunday?",
  empathy:"Are you scared about the responsibility and needing time to explore your feelings?",
  tip:"Fundamental differences sometimes need a couples counselor to explore safely." },
{ id:"love-18", title:"Snoring and sleep", context:"Hamza snores loudly and his wife Leila hasn’t slept through the night in weeks.", who:"adult", level:1,
  jackal:"Your snoring is unbearable. I can’t take it anymore.",
  giraffe:{ o:"I’ve been woken up by snoring most nights for the past few weeks.", f:"I feel exhausted", n:"because I need rest", r:"Would you be willing to see a doctor about it this month?" },
  say:"I’ve been waking up from your snoring most nights and I’m wiped out. I need rest, and I’m a bit worried for your health too. Would you see a doctor about it this month?",
  empathy:"Are you worried about it too, and maybe embarrassed?",
  tip:"Approach as a shared problem with a health angle, not a complaint." },
{ id:"love-19", title:"Posting the relationship", context:"Zara posted a photo of herself and her girlfriend Emma online without asking.", who:"adult", level:1,
  jackal:"Why would you post that without asking? So thoughtless.",
  giraffe:{ o:"You posted a photo of us without checking with me.", f:"I feel uneasy", n:"because I need privacy and choice about what I share", r:"Would you be willing to ask me before posting photos of me?" },
  say:"Zara, I saw you posted the photo of us. I feel a bit uneasy, because privacy matters to me. Could you check with me before posting pictures of me?",
  empathy:"Were you excited about us and wanting to share your happiness?",
  tip:"Different comfort levels with sharing are common; agree on a default rule." },
{ id:"love-20", title:"Stonewalling in fights", context:"Whenever they argue, Chris goes silent and leaves the room, leaving his wife Mei frustrated.", who:"adult", level:3,
  jackal:"You always run away like a coward.",
  giraffe:{ o:"When we argue, you go quiet and leave the room.", f:"I feel lonely and anxious", n:"because I need resolution and connection", r:"Would you be willing to say “I need 20 minutes” and come back to talk?" },
  say:"When we argue and you leave without saying anything, I feel lonely and anxious. I want us to work through things. Could you say “I need 20 minutes” and then come back?",
  empathy:"Are you feeling overwhelmed and needing a break to calm down?",
  tip:"Gottman calls stonewalling a sign of flooding; agreed breaks of about 20 minutes can help both partners calm down." },
{ id:"love-21", title:"Friend I don’t like", context:"Andrés invites his friend Carlos over every weekend, and Carlos makes sarcastic comments about Andrés’s partner Lena.", who:"adult", level:2,
  jackal:"Your friend is a jerk, and you never defend me.",
  giraffe:{ o:"Carlos made three jokes about my job last Saturday.", f:"I feel hurt", n:"because I need respect and support", r:"Could we see Carlos out instead of at home for a while?" },
  say:"Last Saturday Carlos made a few jokes about my job, and it hurt. I want to feel supported. Could we see him out for a while instead of at our place?",
  empathy:"Are you torn between your friend and me, needing harmony?",
  tip:"Ask for a change in arrangement rather than demanding they drop a friend." },
{ id:"love-22", title:"Long-distance calls", context:"In a long-distance relationship, Kenji wants daily calls, but Ava prefers a few longer calls a week.", who:"adult", level:2,
  jackal:"If you loved me, you’d want to talk every day.",
  giraffe:{ o:"We’ve talked twice this week.", f:"I feel lonely", n:"because I need connection and reassurance", r:"Could we add a short good-night message on the days we don’t call?" },
  say:"We’ve talked twice this week, and I’ve been feeling lonely. Could we add a quick good-night message on days we don’t call?",
  empathy:"Do you need some space and flexibility in your schedule?",
  tip:"Find low-effort rituals that meet the need for connection." }
]}
,
{ id:"friends", name:"Friendships", icon:"🤝", hue:160, blurb:"Keep friendships honest and warm through cancellations, gossip, boundaries and change.", cases:[
{ id:"friends-01", title:"Cancels again", context:"For the third time this month, Rosa’s friend Jade cancels their coffee plans an hour before.", who:"peer", level:1,
  jackal:"You always flake on me. I don’t know why I bother.",
  giraffe:{ o:"This is the third time this month our plans have been cancelled on the day.", f:"I feel disappointed", n:"because I value time together and reliability", r:"Would you be willing to tell me a day ahead if you’re not sure you can make it?" },
  say:"Jade, this is the third cancel this month and I’m honestly disappointed — I love our time together. Could you let me know a day ahead if you’re not sure you can make it?",
  empathy:"Are you feeling overwhelmed lately and needing some flexibility?",
  tip:"Ask if something’s going on; frequent cancellations sometimes signal stress or depression." },
{ id:"friends-02", title:"Unpaid loan", context:"Three months ago, Ivan lent his friend Dmitri $300, and it hasn’t been mentioned since.", who:"peer", level:2,
  jackal:"You owe me money, man. Are you just going to pretend it never happened?",
  giraffe:{ o:"It’s been three months since I lent you the $300.", f:"I feel uneasy", n:"because I need clarity and trust between us", r:"Could we agree on a date when you can pay it back, even in instalments?" },
  say:"Dmitri, it’s a bit awkward, but it’s been three months since the $300. I want things clear between us. Could we agree on a date or a few instalments?",
  empathy:"Are you feeling embarrassed or financially stretched right now?",
  tip:"Clear, unemotional money talk protects friendships; set terms at the time you lend." },
{ id:"friends-03", title:"Shared my secret", context:"Kemi learns that her friend Lola told others in their group about Kemi’s miscarriage.", who:"peer", level:3,
  jackal:"I can’t believe you. You can’t keep your mouth shut.",
  giraffe:{ o:"I heard from Tunde that you told others about my miscarriage.", f:"I feel hurt and shaken", n:"because I need trust and privacy around something so painful", r:"Would you be willing to talk with me about what happened?" },
  say:"Lola, I heard you shared about my miscarriage with others. I feel really hurt — it was so private and painful. Can we talk about what happened?",
  empathy:"Were you worried about me and wanting others to support me?",
  tip:"Hear their side before deciding what the friendship needs; repair is sometimes possible." },
{ id:"friends-04", title:"Drifting apart", context:"Best friends since school, Hannah and Grace now rarely talk since Grace moved cities.", who:"peer", level:2,
  jackal:"I guess you’ve got new friends now and don’t need me.",
  giraffe:{ o:"We’ve talked twice since you moved in March.", f:"I feel sad", n:"because I value our friendship and want to stay connected", r:"Would you be up for a video call on the first Sunday of each month?" },
  say:"Grace, I realized we’ve only talked twice since you moved, and I miss you. Would you be up for a video call the first Sunday of each month?",
  empathy:"Are you feeling stretched adjusting to a new place?",
  tip:"Recurring rituals keep long-distance friendships alive without relying on spontaneity." },
{ id:"friends-05", title:"Left out of group chat", context:"Leo discovers his friends made a new group chat without him to plan a weekend trip.", who:"peer", level:2,
  jackal:"Nice to know who my real friends are.",
  giraffe:{ o:"I saw there’s a chat planning the trip that I’m not in.", f:"I feel hurt and confused", n:"because I need belonging and honesty", r:"Can you tell me what happened?" },
  say:"Hey Max, I noticed there’s a trip chat I’m not in, and I feel hurt and a bit confused. Can you help me understand what happened?",
  empathy:"Was it maybe a smaller trip or an oversight, and you didn’t want to make it awkward?",
  tip:"Ask one trusted friend directly instead of posting about it." },
{ id:"friends-06", title:"Missed my big day", context:"Aisha’s close friend Yasmin didn’t come to her graduation party and didn’t text.", who:"peer", level:2,
  jackal:"You couldn’t even show up for me once.",
  giraffe:{ o:"You weren’t at my graduation party and I didn’t hear from you.", f:"I felt sad", n:"because I want to share important moments with you", r:"Would you tell me what happened?" },
  say:"Yasmin, I missed you at my party, and when I didn’t hear from you I felt sad. You matter so much to me. Can you tell me what happened?",
  empathy:"Was something going on that made it hard to come or to reach out?",
  tip:"Start from curiosity; there may be a story you don’t know." },
{ id:"friends-07", title:"Late-night crisis calls", context:"Nearly every night, Ellie’s friend Sasha calls after midnight in distress about her relationship.", who:"peer", level:3,
  jackal:"I can’t keep doing this. Fix your life.",
  giraffe:{ o:"You’ve called after midnight most nights this week.", f:"I feel caring and also exhausted", n:"because I want to support you and also need sleep", r:"Would you be willing to call me before 10, and could we look together at finding a counsellor?" },
  say:"Sasha, I care about you so much. You’ve called after midnight most nights, and I’m exhausted. Could we talk before 10, and can I help you find a counsellor too?",
  empathy:"Are you feeling desperate and lonely, needing support and stability?",
  tip:"If a friend talks about harming themselves, help them reach professional or emergency support right away." },
{ id:"friends-08", title:"Returned it damaged", context:"Pablo lent his friend Andre his camera, and it came back with a cracked lens.", who:"peer", level:1,
  jackal:"You broke my camera. You’re so careless.",
  giraffe:{ o:"The camera lens has a crack that wasn’t there before.", f:"I feel upset", n:"because I value care with my things", r:"Would you be willing to split the repair cost with me?" },
  say:"Andre, the lens came back with a crack. I’m pretty upset. Would you be willing to split the repair cost?",
  empathy:"Do you feel bad about it and maybe weren’t sure how to bring it up?",
  tip:"Address it calmly and quickly; small resentments grow if left unspoken." },
{ id:"friends-09", title:"Always late", context:"Every time they meet, Tomás’s friend Nico arrives at least 30 minutes late.", who:"peer", level:1,
  jackal:"Do you own a watch? You’re always late.",
  giraffe:{ o:"The last four times we met, you arrived 30 minutes after we said.", f:"I feel frustrated", n:"because I value my time", r:"Would you text when you leave so I know when to head out?" },
  say:"Nico, the last four times you were about half an hour late, and I get frustrated sitting around. Could you text when you leave so I know when to head out?",
  empathy:"Do you have a lot on your plate and find it hard to estimate time?",
  tip:"Offer a practical workaround that meets your need regardless of their habit." },
{ id:"friends-10", title:"Dominates conversation", context:"In catch-ups with friend Rachel, Jen notices she barely gets to speak about her own life.", who:"peer", level:1,
  jackal:"It’s always about you.",
  giraffe:{ o:"In our last coffee, we talked about your work for most of the hour.", f:"I feel a little sad", n:"because I want to share my news too", r:"Would you be up for hearing about my new job now?" },
  say:"Rach, I love hearing about your work. I’ve got some news too — would you be up for hearing about my new job?",
  empathy:"Are you going through a lot and needing someone to listen?",
  tip:"Sometimes the simplest move is asking for a turn." },
{ id:"friends-11", title:"Friend’s rude partner", context:"Gemma’s best friend Becky’s new boyfriend makes snide comments about Gemma whenever they all meet.", who:"peer", level:3,
  jackal:"Your boyfriend is a jerk. I don’t know what you see in him.",
  giraffe:{ o:"When we meet, Jake comments on my clothes.", f:"I feel uncomfortable", n:"because I want respect and time with you", r:"Could we meet just the two of us sometimes?" },
  say:"Becky, when Jake comments on my clothes, I feel uncomfortable. I really want time with you. Could we meet just the two of us sometimes?",
  empathy:"Are you feeling torn and wanting everyone to get along?",
  tip:"Speak only to your experience; criticizing their partner often pushes a friend away." },
{ id:"friends-12", title:"Comments on my weight", context:"At lunch, friend Farah says to Noura, “Are you sure you want dessert? You’ve gained weight.”", who:"peer", level:2,
  jackal:"Mind your own business.",
  giraffe:{ o:"When you mentioned my weight just now,", f:"I felt hurt", n:"because I need acceptance and to make my own choices about food", r:"Would you be willing to not comment on my body?" },
  say:"Farah, when you mentioned my weight, it hurt. I need to make my own food choices without comments. Could you not remark on my body?",
  empathy:"Were you worried about my health and wanting to care for me?",
  tip:"Remarks about bodies are rarely helpful; a clear, kind boundary is enough." },
{ id:"friends-13", title:"Envy at friend’s success", context:"Tobi feels a pang of envy when his friend Wale announces a dream job offer.", who:"self", level:2,
  jackal:"Must be nice to have everything handed to you.",
  giraffe:{ o:"When Wale told me about his job offer,", f:"I felt happy for him and also envious", n:"because I long for progress and recognition in my own career", r:"Can I congratulate him sincerely and then write down one step toward my own goal this week?" },
  say:"Wale, congratulations, that’s amazing! (To myself: I’m a bit envious because I want growth too. I’ll take one step this week.)",
  empathy:"Am I feeling stuck and needing hope about my own path?",
  tip:"Envy points to your own unmet needs; use it as information, not a verdict." },
{ id:"friends-14", title:"Jokes at my expense", context:"In the friend group, Arjun often jokes about Dev’s accent.", who:"peer", level:2,
  jackal:"Real funny, Arjun. You’re hilarious.",
  giraffe:{ o:"When you joke about my accent,", f:"I feel uncomfortable", n:"because I need respect", r:"Would you be willing to stop those jokes?" },
  say:"Arjun, I know it’s meant as fun, but the accent jokes don’t sit well with me. Can you drop them?",
  empathy:"Were you trying to connect and have fun with the group?",
  tip:"Raising it privately can feel safer than in front of the group." },
{ id:"friends-15", title:"Splitting the bill", context:"At dinner, Sophie ordered only a salad, but her friends propose splitting the bill equally after ordering steak and wine.", who:"group", level:1,
  jackal:"I’m not paying for your expensive dinner.",
  giraffe:{ o:"I had a salad and water, and splitting evenly means I’d pay about $40.", f:"I feel uneasy", n:"because I value fairness and need to manage my budget", r:"Would everyone be okay with paying for what we ordered tonight?" },
  say:"Hey, I just had a salad and water, and an even split would be about $40 for me. I’m on a tight budget — would everyone be okay paying for what we ordered tonight?",
  empathy:"Are you wanting to keep things simple and easy?",
  tip:"Mention it before the bill arrives; it feels less awkward." },
{ id:"friends-16", title:"Pressured to drink", context:"At a bar, friend Matt keeps urging Ben, who’s not drinking this month, to “just have one.”", who:"peer", level:1,
  jackal:"Stop pushing, you sound like an idiot.",
  giraffe:{ o:"You’ve asked me to have a drink three times tonight.", f:"I feel annoyed", n:"because I need respect for my choices", r:"Could you let it go for tonight?" },
  say:"Matt, that’s the third time you’ve asked. I’m not drinking this month, and I want that respected. Can you let it go tonight?",
  empathy:"Are you wanting us all to have fun together?",
  tip:"A short, confident no is often enough; you don’t owe a long explanation." },
{ id:"friends-17", title:"Unflattering photo posted", context:"Friend Chloe posted a group photo where Mia is mid-sneeze.", who:"peer", level:1,
  jackal:"Why would you post that? You did that on purpose.",
  giraffe:{ o:"The photo you posted has me mid-sneeze.", f:"I feel embarrassed", n:"because I want some say over how I’m shown online", r:"Would you be willing to take it down or crop me out?" },
  say:"Chloe, that photo has me mid-sneeze — I’m a bit embarrassed! Could you take it down or crop me out?",
  empathy:"Were you excited to share a fun night?",
  tip:"Keep it light; most people happily fix it." },
{ id:"friends-18", title:"Unsolicited parenting advice", context:"Friend Oksana repeatedly tells new mom Lucy she should sleep train her baby.", who:"peer", level:2,
  jackal:"You don’t even have kids. Stop telling me what to do.",
  giraffe:{ o:"You’ve mentioned sleep training a few times this week.", f:"I feel tense", n:"because I need trust in my choices as a parent", r:"Would you be willing to support me even if I choose differently?" },
  say:"Oksana, you’ve mentioned sleep training a few times. I know you care. I need to trust my own choices right now — can you support me even if I decide differently?",
  empathy:"Are you worried about me getting enough rest?",
  tip:"Acknowledge the care behind advice; you can thank and still decline." },
{ id:"friends-19", title:"I said the wrong thing", context:"When Sun-hee’s father died, her friend Mariam said, “At least he lived a long life,” and Sun-hee went quiet.", who:"peer", level:2,
  jackal:"I didn’t mean anything by it. You’re too sensitive.",
  giraffe:{ o:"When I said “at least he lived a long life,” you went quiet.", f:"I feel regretful", n:"because I want to support you in your grief", r:"Would you be willing to tell me what would help most right now?" },
  say:"Sun-hee, I’ve been thinking about what I said about your dad, and I’m sorry. I want to be there for you. What would help most right now?",
  empathy:"Are you feeling raw and needing your loss to be fully seen?",
  tip:"Avoid “at least” in condolences; simply being present matters more than finding the right words." },
{ id:"friends-20", title:"Welcoming someone new", context:"Lina wants to invite her new colleague Haruto to her long-standing friend group’s board game night.", who:"group", level:1,
  jackal:"You guys are so cliquey. Just let him come.",
  giraffe:{ o:"I’ve met someone at work who loves board games.", f:"I feel excited", n:"because I value inclusion and fun", r:"Would everyone be open to me inviting Haruto next Friday?" },
  say:"I met Haruto at work and he loves board games. I’d love for him to join. Would everyone be open to me inviting him next Friday?",
  empathy:"Are some of you wanting to keep the closeness and familiarity of our group?",
  tip:"Ask the group first; it respects everyone’s need for choice." },
{ id:"friends-21", title:"Roommate skips bills", context:"Roommate and friend Kyle hasn’t paid his share of utilities for two months.", who:"peer", level:2,
  jackal:"You’re a freeloader. I’m not your bank.",
  giraffe:{ o:"I’ve covered your share of the utilities for two months.", f:"I feel anxious", n:"because I need fairness and financial security", r:"Could you transfer the $180 by Friday?" },
  say:"Kyle, I’ve covered your utilities for two months, and I’m getting anxious about money. Could you transfer the $180 by Friday?",
  empathy:"Are you short on cash and feeling embarrassed to bring it up?",
  tip:"Use a shared expenses app; it keeps money conversations factual." },
{ id:"friends-22", title:"Only calls for favours", context:"Lately, Aaron’s friend Jamal only reaches out when he needs help moving or a lift.", who:"peer", level:2,
  jackal:"You only call when you want something.",
  giraffe:{ o:"The last three times you’ve called, it was to ask for help.", f:"I feel disappointed and a little sad", n:"because I want mutual friendship", r:"Could we hang out just for fun this weekend?" },
  say:"Jamal, happy to help sometimes. I noticed the last few calls were for favours, and I miss just hanging out. How about something fun this weekend?",
  empathy:"Are you going through a busy, stressful time?",
  tip:"Name the pattern without accusation, then invite the connection you want." }
]}
,
{ id:"teens", name:"Teens & Peer Pressure", icon:"🎧", hue:270, blurb:"Navigate curfews, phones, parties and pressure with honesty on both sides of the conversation.", cases:[
{ id:"teens-01", title:"Broken curfew", context:"Sixteen-year-old Nia came home at 1 a.m., two hours after her curfew, without calling.", who:"teen", level:2,
  jackal:"You’re grounded for a month. You can’t be trusted.",
  giraffe:{ o:"You came home at one, two hours after we agreed, and I didn’t hear from you.", f:"I was scared", n:"because I need to know you’re safe", r:"Would you be willing to talk tomorrow about how we can make this work?" },
  say:"Nia, I was so scared when it got to one and I hadn’t heard from you. I need to know you’re safe. Let’s sleep, and tomorrow can we talk about how to make curfew work?",
  empathy:"Were you having a great time and wanting more freedom and trust?",
  tip:"Wait until you’re calm; a late-night lecture rarely lands." },
{ id:"teens-02", title:"Asking for later curfew", context:"Seventeen-year-old Ali wants to ask his parents to extend his curfew from 10 to midnight on weekends.", who:"adult", level:1,
  jackal:"You treat me like a baby. Everyone else gets to stay out later.",
  giraffe:{ o:"My curfew’s been 10 for two years, and I’ve been home on time every weekend this term.", f:"I feel hopeful", n:"because I want more independence and trust", r:"Would you be willing to try midnight for the next month and see how it goes?" },
  say:"Mum, Dad, I’ve been home on time every weekend this term. I’d love more independence. Could we try a midnight curfew for a month and then review it?",
  empathy:"Are you worried about my safety and needing reassurance?",
  tip:"Proposing a trial with a review shows maturity and makes yes easier." },
{ id:"teens-03", title:"Dating someone older", context:"Fifteen-year-old Bianca is dating a 19-year-old, and her mother Rosa is alarmed.", who:"teen", level:3,
  jackal:"You’re not seeing him again. He’s a creep, end of story.",
  giraffe:{ o:"You’ve told me Leo is 19.", f:"I feel worried", n:"because I need to know you’re safe and respected", r:"Would you be willing to tell me more about him and how you met?" },
  say:"Bianca, I’m really worried knowing Leo is 19 and you’re 15. I care about your safety. Can you tell me more about him and how you met?",
  empathy:"Are you feeling special and grown-up, wanting to be trusted?",
  tip:"Stay connected; banning outright often drives the relationship underground. Know the age-of-consent laws where you live and act on safety concerns." },
{ id:"teens-04", title:"Found a vape", context:"While doing laundry, Mr. Ochoa finds a vape pen in his 14-year-old son Mateo’s jeans.", who:"teen", level:3,
  jackal:"Drugs now? I’m so ashamed of you.",
  giraffe:{ o:"I found a vape in your jeans pocket.", f:"I feel worried", n:"because I care about your health", r:"Would you be willing to talk with me about it after dinner?" },
  say:"Mateo, I found a vape in your jeans pocket. I’m worried, because I care a lot about your health. Can we talk after dinner? I want to hear your side.",
  empathy:"Are you wanting to fit in, or to find a way to deal with stress?",
  tip:"Curiosity first; teens open up when they don’t expect an immediate punishment." },
{ id:"teens-05", title:"Pushed to drink at a party", context:"At a party, Ella’s friends keep handing her shots and calling her boring when she declines.", who:"peer", level:2,
  jackal:"You guys are so immature.",
  giraffe:{ o:"I’ve said no three times.", f:"I feel annoyed", n:"because I want my choices respected", r:"Could you stop offering?" },
  say:"I’ve said no three times. I’m good, honestly. Can you stop offering? Let’s dance instead.",
  empathy:"Are you wanting everyone to loosen up and have fun together?",
  tip:"Have an exit plan: a code word text to a parent for a no-questions-asked pickup." },
{ id:"teens-06", title:"Hidden report card", context:"Mrs. Kowalski finds out her 15-year-old son Adam hid a failing maths grade.", who:"teen", level:2,
  jackal:"You lied to me. You’re lazy and dishonest.",
  giraffe:{ o:"The school told me you have an F in maths and I hadn’t heard from you.", f:"I feel disappointed and worried", n:"because I value honesty and want to support your learning", r:"Could we sit down tonight and make a plan together?" },
  say:"Adam, the school told me about the F in maths. I’m disappointed you didn’t tell me, and I’m worried. Can we sit down tonight and make a plan together?",
  empathy:"Were you feeling ashamed and scared of how I’d react?",
  tip:"If teens hide things, ask yourself whether they feel safe telling you bad news." },
{ id:"teens-07", title:"Oversharing online", context:"Thirteen-year-old Lila has been posting her school name and location on a public social media account.", who:"teen", level:2,
  jackal:"Do you want a stalker? Give me your phone now.",
  giraffe:{ o:"Your public profile shows your school and where you are.", f:"I feel worried", n:"because I care about your safety", r:"Would you be willing to go through your privacy settings with me tonight?" },
  say:"Lila, I noticed your public profile shows your school and location. That worries me for your safety. Could we go through your privacy settings together tonight?",
  empathy:"Are you wanting to connect with friends and feel part of things?",
  tip:"Teach skills side by side rather than confiscating; it builds lasting habits." },
{ id:"teens-08", title:"Coming out", context:"Sixteen-year-old Sam tells their father, Michael, that they’re non-binary.", who:"teen", level:3,
  jackal:"It’s just a phase. You’re too young to know.",
  giraffe:{ o:"You’ve just told me you’re non-binary.", f:"I feel touched you trusted me, and I’m also unsure how to support you", n:"because I love you and want you to feel accepted", r:"Would you be willing to help me understand what this means for you?" },
  say:"Sam, thank you for telling me. I love you, and I want you to feel accepted. I’m still learning — can you help me understand what this means for you?",
  empathy:"Are you feeling nervous and hoping for love and acceptance?",
  tip:"Your first response matters enormously; lead with love and curiosity even if you need time to process." },
{ id:"teens-09", title:"Job vs. homework", context:"Seventeen-year-old Kai works 20 hours a week at a café, and his grades are slipping.", who:"teen", level:2,
  jackal:"Quit that job, it’s ruining your future.",
  giraffe:{ o:"You’re working 20 hours a week and your grades dropped this term.", f:"I feel concerned", n:"because I value your education and your independence", r:"Could we look at your schedule together and find a balance?" },
  say:"Kai, I love that you’re earning your own money. With 20 hours a week and your grades slipping, I’m a bit concerned. Could we look at your schedule together and find a balance?",
  empathy:"Are you proud of earning money and wanting independence?",
  tip:"Respect their goals; problem-solve together rather than dictating." },
{ id:"teens-10", title:"Stop reading my messages", context:"Fifteen-year-old Zainab discovers her mother has been reading her text messages.", who:"adult", level:2,
  jackal:"You’re so controlling! I hate you!",
  giraffe:{ o:"I saw that you read my messages.", f:"I feel hurt and upset", n:"because I need privacy and trust", r:"Would you be willing to talk with me instead of reading my phone?" },
  say:"Mum, I found out you read my messages, and I feel really hurt. I need some privacy and trust. If you’re worried, could you talk to me instead?",
  empathy:"Are you worried about my safety and wanting to protect me?",
  tip:"Parents and teens can agree together on what privacy looks like and when checking in is needed." },
{ id:"teens-11", title:"Mocked in group chat", context:"Classmates are sharing memes mocking 14-year-old Diego in a group chat.", who:"peer", level:3,
  jackal:"You’re all pathetic losers.",
  giraffe:{ o:"There are memes about me in this chat.", f:"I feel hurt and angry", n:"because I want respect", r:"Will you delete them now?" },
  say:"These memes about me aren’t funny to me. I want respect. Please delete them now.",
  empathy:"Are some of you wanting to fit in and get laughs?",
  tip:"Screenshot the messages and tell a trusted adult; you don’t have to deal with cyberbullying alone." },
{ id:"teens-12", title:"Can I copy your test?", context:"During a test, Liam’s friend Jake whispers that he wants to copy Liam’s answers.", who:"peer", level:1,
  jackal:"No way, do your own work.",
  giraffe:{ o:"You’re asking to copy my answers.", f:"I feel uncomfortable", n:"because I value honesty", r:"Would you like to study together before the next test?" },
  say:"Sorry, man, I’m not comfortable with that. Want to study together before the next one?",
  empathy:"Are you feeling stressed and unprepared?",
  tip:"Offer real help afterwards; it keeps the friendship intact." },
{ id:"teens-13", title:"Phone at family dinner", context:"Thirteen-year-old Ruby texts through every family dinner.", who:"teen", level:1,
  jackal:"You’re so rude. Put that thing away.",
  giraffe:{ o:"You’ve been texting during dinner most nights.", f:"I feel sad", n:"because I want connection with you", r:"Would you put your phone in the basket during dinner?" },
  say:"Ruby, I’ve noticed texting at dinner most nights. I miss chatting with you. Could phones go in the basket during dinner — mine too?",
  empathy:"Are you worried about missing something with your friends?",
  tip:"Model it yourself; teens follow what we do more than what we say." },
{ id:"teens-14", title:"Lie to your parents for me", context:"Sixteen-year-old Jess asks her best friend Hana to tell Jess’s parents she’s sleeping over at Hana’s.", who:"peer", level:2,
  jackal:"Are you crazy? I’m not getting dragged into your mess.",
  giraffe:{ o:"You’re asking me to cover for you.", f:"I feel uneasy", n:"because I value honesty and want you safe", r:"Would you be willing to tell me where you’re actually going?" },
  say:"Jess, I care about you, but I’m not comfortable lying to your parents. Can you tell me where you’re actually going? I want you safe.",
  empathy:"Are you wanting freedom and fun without feeling judged?",
  tip:"You can be a loyal friend and still say no to lying." },
{ id:"teens-15", title:"Wants to quit soccer", context:"Fourteen-year-old Omar wants to quit the soccer team his parents pay for.", who:"teen", level:2,
  jackal:"We spent a fortune. You’re not a quitter.",
  giraffe:{ o:"You’ve said you want to quit soccer.", f:"I feel surprised", n:"because I want to understand what matters to you", r:"Would you tell me what’s changed?" },
  say:"Omar, I was surprised to hear you want to quit. I want to understand. What’s changed for you?",
  empathy:"Are you wanting to explore other interests and have more choice?",
  tip:"Listen before deciding; quitting may signal bullying, burnout, or new passions." },
{ id:"teens-16", title:"Let’s skip class", context:"Friends urge 15-year-old Ayo to skip chemistry and go to the mall.", who:"peer", level:1,
  jackal:"You guys are going to fail.",
  giraffe:{ o:"You want me to skip chemistry.", f:"I feel torn", n:"because I want fun with you and also to keep up", r:"Could we meet at the mall after school?" },
  say:"Sounds fun, but I can’t skip chemistry. Meet you at the mall after school?",
  empathy:"Are you wanting a break and fun with friends?",
  tip:"Suggesting an alternative keeps you included without giving in." },
{ id:"teens-17", title:"Friend talks about self-harm", context:"Fifteen-year-old Leah confides to her friend Maya that she has been cutting herself.", who:"peer", level:3,
  jackal:"That’s crazy, why would you do that?",
  giraffe:{ o:"You told me you’ve been cutting.", f:"I feel scared and caring", n:"because I want you safe and supported", r:"Will you come with me to talk to the school counsellor today?" },
  say:"Leah, thank you for trusting me. I’m scared because I care about you. I want you to have real support. Will you come with me to the counsellor today?",
  empathy:"Are you feeling overwhelmed and needing relief and understanding?",
  tip:"This is a secret you shouldn’t keep; telling a trusted adult is an act of friendship." },
{ id:"teens-18", title:"Friend drives too fast", context:"Seventeen-year-old Ethan rides with his friend Josh, who speeds on the highway.", who:"peer", level:3,
  jackal:"You drive like a maniac.",
  giraffe:{ o:"You’re going 90 in a 60 zone.", f:"I feel scared", n:"because I need safety", r:"Could you slow down now?" },
  say:"Josh, we’re doing 90 in a 60 and I’m honestly scared. Please slow down now.",
  empathy:"Are you wanting excitement or to show off a bit?",
  tip:"If the driver won’t slow down, ask to get out at the next safe spot and call someone." },
{ id:"teens-19", title:"Sister borrows clothes", context:"Fourteen-year-old Ana keeps finding her sister Elena wearing her clothes without asking.", who:"peer", level:1,
  jackal:"Stop stealing my clothes!",
  giraffe:{ o:"You’re wearing my jacket and didn’t ask.", f:"I feel annoyed", n:"because I want respect for my things", r:"Would you ask me first next time?" },
  say:"Elena, that’s my jacket — I’m annoyed you didn’t ask. Can you check with me first next time?",
  empathy:"Do you love my style and want to share?",
  tip:"Clear simple rules reduce sibling conflict." },
{ id:"teens-20", title:"College pressure", context:"Seventeen-year-old Wei feels overwhelmed by his parents’ expectations for top universities.", who:"adult", level:2,
  jackal:"Stop nagging me! You only care about my grades.",
  giraffe:{ o:"You’ve asked about my college list every day this week.", f:"I feel overwhelmed", n:"because I need support and some space", r:"Could we talk about applications just once a week on Sundays?" },
  say:"Mom, Dad, you’ve asked about my college list every day this week, and I’m overwhelmed. I know you care. Could we talk about it once a week, maybe Sundays?",
  empathy:"Are you worried about my future and wanting to help me succeed?",
  tip:"Propose a structure; it reassures parents and gives you space." },
{ id:"teens-21", title:"After being rejected", context:"Sixteen-year-old Lucas asked someone to the dance and was turned down in front of others.", who:"self", level:2,
  jackal:"I’m such a loser. No one will ever like me.",
  giraffe:{ o:"I asked Mia to the dance and she said no.", f:"I feel embarrassed and sad", n:"I need acceptance and kindness toward myself", r:"Can I text a friend and do something fun tonight?" },
  say:"I asked Mia and she said no. I’m embarrassed and sad, and that’s okay. It took courage to ask. I’ll text Sam and do something fun tonight.",
  empathy:"Am I wanting to feel liked and to belong?",
  tip:"Rejection stings, but it doesn’t define you; acknowledge the courage it took." },
{ id:"teens-22", title:"Pressured for photos", context:"Fifteen-year-old Nadia’s boyfriend keeps asking her to send revealing photos.", who:"peer", level:3,
  jackal:"You’re gross. Leave me alone.",
  giraffe:{ o:"You’ve asked me for photos like that several times.", f:"I feel uncomfortable", n:"because I need respect and safety", r:"Will you stop asking?" },
  say:"I’ve told you I don’t want to send photos like that. I feel uncomfortable. I need you to respect that and stop asking.",
  empathy:"Are you wanting closeness or feeling pressure from others?",
  tip:"Anyone who keeps pressuring you isn’t respecting you; tell a trusted adult. Sharing such images of minors is illegal in many places." }
]}
);
